@_ods_cext.register_operation(_Dialect)
class GemmOp(_ods_ir.OpView):
    OPERATION_NAME = "tilelang.gemm"

    _ODS_REGIONS = (0, True)

    def __init__(
        self,
        a,
        b,
        c,
        *,
        transpose_a: _Optional[bool] = None,
        transpose_b: _Optional[bool] = None,
        clear_accum: _Optional[bool] = None,
        loc: _Optional[_ods_ir.Location] = None,
        ip: _Optional[_ods_ir.InsertionPoint] = None,
    ):
        attributes: dict = {}
        _ods_context = _ods_get_default_loc_context(loc)
        if transpose_a:
            attributes["transpose_a"] = _ods_ir.UnitAttr.get(_ods_context)
        if transpose_b:
            attributes["transpose_b"] = _ods_ir.UnitAttr.get(_ods_context)
        if clear_accum:
            attributes["clear_accum"] = _ods_ir.UnitAttr.get(_ods_context)
        super().__init__(
            self.OPERATION_NAME,
            self._ODS_REGIONS,
            None,
            None,
            attributes=attributes,
            results=[],
            operands=[a, b, c],
            successors=None,
            regions=None,
            loc=loc,
            ip=ip,
        )

    @builtins.property
    def a(self):
        return self.operation.operands[0]

    @builtins.property
    def b(self):
        return self.operation.operands[1]

    @builtins.property
    def c(self):
        return self.operation.operands[2]

    @builtins.property
    def transpose_a(self) -> bool:
        return "transpose_a" in self.operation.attributes

    @transpose_a.setter
    def transpose_a(self, value: bool):
        if value:
            self.operation.attributes["transpose_a"] = _ods_ir.UnitAttr.get()
        elif "transpose_a" in self.operation.attributes:
            del self.operation.attributes["transpose_a"]

    @builtins.property
    def transpose_b(self) -> bool:
        return "transpose_b" in self.operation.attributes

    @transpose_b.setter
    def transpose_b(self, value: bool):
        if value:
            self.operation.attributes["transpose_b"] = _ods_ir.UnitAttr.get()
        elif "transpose_b" in self.operation.attributes:
            del self.operation.attributes["transpose_b"]

    @builtins.property
    def clear_accum(self) -> bool:
        return "clear_accum" in self.operation.attributes

    @clear_accum.setter
    def clear_accum(self, value: bool):
        if value:
            self.operation.attributes["clear_accum"] = _ods_ir.UnitAttr.get()
        elif "clear_accum" in self.operation.attributes:
            del self.operation.attributes["clear_accum"]


# ===========================================================================
# tilelang.scope
# ===========================================================================

@_ods_cext.register_operation(_Dialect)
class ScopeOp(_ods_ir.OpView):
    """Scope region with explicit default, SIMD, or SIMT execution mode.

    Assembly (unregistered dialect form)::

        "tilelang.scope"() ({ ... }) {
          mode = #tilelang.scope_mode<simt>, threads = 128 : ui32
        } : () -> ()
    """

    OPERATION_NAME = "tilelang.scope"

    _ODS_REGIONS = (1, True)

    def __init__(
        self,
        *,
        mode: str,
        threads: _Optional[int] = None,
        loc: _Optional[_ods_ir.Location] = None,
        ip: _Optional[_ods_ir.InsertionPoint] = None,
    ):
        attributes: dict = {}
        if mode not in ("default", "simd", "simt"):
            raise ValueError(
                "ScopeOp mode must be one of 'default', 'simd', or 'simt', "
                f"got {mode!r}"
            )
        if mode == "simt" and threads is None:
            raise ValueError("ScopeOp SIMT mode requires threads")
        if mode != "simt" and threads is not None:
            raise ValueError("ScopeOp threads are only valid in SIMT mode")
        attributes["mode"] = _ods_ir.Attribute.parse(
            f"#tilelang.scope_mode<{mode}>"
        )
        if threads is not None:
            if isinstance(threads, bool) or not isinstance(threads, int):
                raise TypeError("ScopeOp threads must be a uint32 integer")
            if not 1 <= threads <= (1 << 32) - 1:
                raise ValueError(
                    "ScopeOp threads must be in the uint32 range "
                    "[1, 4294967295]"
                )
            attributes["threads"] = _ods_ir.IntegerAttr.get(
                _ods_ir.IntegerType.get_unsigned(32), threads
            )
        super().__init__(
            self.OPERATION_NAME,
            self._ODS_REGIONS,
            None,
            None,
            attributes=attributes,
            results=[],
            operands=[],
            successors=None,
            regions=None,
            loc=loc,
            ip=ip,
        )

    @builtins.property
    def body(self) -> _ods_ir.Region:
        return self.regions[0]

    @builtins.property
    def mode(self):
        return self.operation.attributes["mode"]

    @builtins.property
    def threads(self) -> _Optional[int]:
        if "threads" not in self.operation.attributes:
            return None
        return _ods_ir.IntegerAttr(self.operation.attributes["threads"]).value


